(2549150, 350448, 58785, '<td valign="top">Very nice shot, and very nice border with the photo :) 8</td>', 'Very nice shot, and very nice border with the photo :) 8', '2006-06-24 17:20:15.000000', NULL, 1),
(2549151, 351010, 29770, '<td valign="top">Very sharp focus on the foreground subject.  Interesting colors, especially on the bug.</td>', 'Very sharp focus on the foreground subject.  Interesting colors, especially on the bug.', '2006-06-24 17:20:48.000000', NULL, 1),
(2549152, 350169, 29770, '<td valign="top">The colors are very interesting in this image.  I think the flowers in the background add a lot to the image.  Nice Shot.</td>', 'The colors are very interesting in this image.  I think the flowers in the background add a lot to the image.  Nice Shot.', '2006-06-24 17:21:07.000000', NULL, 1),
