(2557933, 350971, 55738, '<td valign="top">Beautiful saturation decisions!</td>', 'Beautiful saturation decisions!', '2006-06-27 13:14:20.000000', NULL, 1),
(2557935, 348346, 70, '<td valign="top">Love this!</td>', 'Love this!', '2006-06-27 13:15:24.000000', NULL, 1),
(2557941, 350672, 30625, '<td valign="top">The contrasting colors are just awesome to look at. Well done. I just dont know how well flower shots are going to do with so many in this challenge. Good Luck.</td>', 'The contrasting colors are just awesome to look at. Well done. I just dont know how well flower shots are going to do with so many in this challenge. Good Luck.', '2006-06-27 13:17:02.000000', NULL, 1),
(2557944, 350881, 70, '<td valign="top">Nice coloring and composure. I think the water drops are a little overdone here...</td>', 'Nice coloring and composure. I think the water drops are a little overdone here...', '2006-06-27 13:17:15.000000', NULL, 1),
(2557947, 350746, 30625, '<td valign="top">Highlights just a little blown out as you can see lose of texture in the highlights.</td>', 'Highlights just a little blown out as you can see lose of texture in the highlights.', '2006-06-27 13:17:57.000000', NULL, 1),
(2557949, 349575, 59138, '<td valign="top">Very Nice, I like how the everything leads your eye to the look on the guys face.  excellent use of bokeh.</td>', 'Very Nice, I like how the everything leads your eye to the look on the guys face.  excellent use of bokeh.', '2006-06-27 13:18:11.000000', NULL, 1),
(2557950, 350829, 30625, '<td valign="top">The overall texture and patterns are spot on. Very pleasing and creative.</td>', 'The overall texture and patterns are spot on. Very pleasing and creative.', '2006-06-27 13:19:09.000000', NULL, 1),
(2557951, 349352, 59138, '<td valign="top">Better if the closest edge of the wing wasn''t out of focus. no real focal point.</td>', 'Better if the closest edge of the wing wasn''t out of focus. no real focal point.', '2006-06-27 13:19:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2557952, 350130, 70, '<td valign="top">Well, the background is fairly well out of focus but it contains some distracting items and there isn''t anything particularly attention-drawing in the foreground.</td>', 'Well, the background is fairly well out of focus but it contains some distracting items and there isn''t anything particularly attention-drawing in the foreground.', '2006-06-27 13:19:49.000000', NULL, 1),
(2557953, 350020, 59138, '<td valign="top">Nice if the sky wasn''t overexposed.</td>', 'Nice if the sky wasn''t overexposed.', '2006-06-27 13:20:09.000000', NULL, 1),
(2557957, 350964, 59138, '<td valign="top">Nice focus for the photo, better if closest legs were not out of focus.  Is the background really bokeh?</td>', 'Nice focus for the photo, better if closest legs were not out of focus.  Is the background really bokeh?', '2006-06-27 13:21:28.000000', NULL, 1),
(2557959, 350192, 55738, '<td valign="top">I adore the shallow DOF here and the whimsy of it.  Excellent work!</td>', 'I adore the shallow DOF here and the whimsy of it.  Excellent work!', '2006-06-27 13:21:50.000000', NULL, 1),
(2557960, 349734, 70, '<td valign="top">Love the shot! Not sure if I especially like the toning - perhaps with a bit more contrast. I''d like to see this shot in color, but great capture!</td>', 'Love the shot! Not sure if I especially like the toning - perhaps with a bit more contrast. I''d like to see this shot in color, but great capture!', '2006-06-27 13:22:02.000000', NULL, 1),
(2557961, 348356, 59138, '<td valign="top">Excellent, nice focus, perhaps a nintendo in the background?  lol, probably would have distracted.</td>', 'Excellent, nice focus, perhaps a nintendo in the background?  lol, probably would have distracted.', '2006-06-27 13:22:13.000000', NULL, 1),
(2557963, 349504, 70, '<td valign="top">Slightly shallow DOF but I don''t really see anything I''d considered bokeh here.</td>', 'Slightly shallow DOF but I don''t really see anything I''d considered bokeh here.', '2006-06-27 13:23:03.000000', NULL, 1),
(2557965, 350670, 59138, '<td valign="top">A little dark.  better if some of those black seeds (?) weren''t out of focus.</td>', 'A little dark.  better if some of those black seeds (?) weren''t out of focus.', '2006-06-27 13:23:08.000000', NULL, 1),
(2557966, 349763, 59138, '<td valign="top">Excellent color, perhaps a bit dark at base of stem.</td>', 'Excellent color, perhaps a bit dark at base of stem.', '2006-06-27 13:23:28.000000', NULL, 1),
(2557967, 348453, 59138, '<td valign="top">better if the bark to the far right didn''t blend with background.   I like the feel of the photo. nice capture.</td>', 'better if the bark to the far right didn''t blend with background.   I like the feel of the photo. nice capture.', '2006-06-27 13:24:00.000000', NULL, 1),
(2557968, 349240, 70, '<td valign="top">Looks like the lower "road" to me. ;) Nice shot. A little hot on the bug.</td>', 'Looks like the lower "road" to me. ;) Nice shot. A little hot on the bug.', '2006-06-27 13:24:11.000000', NULL, 1),
(2557972, 349415, 59138, '<td valign="top">Better if the hit wasn''t blocked by the ropes.  Interesting how the main subject is blurred, but I like it.</td>', 'Better if the hit wasn''t blocked by the ropes.  Interesting how the main subject is blurred, but I like it.', '2006-06-27 13:25:08.000000', NULL, 1),
(2557973, 349876, 59138, '<td valign="top">Far edge of wing a bit blurred, but nice.  I love the way your eyes are drawn right to those "eyes"</td>', 'Far edge of wing a bit blurred, but nice.  I love the way your eyes are drawn right to those "eyes"', '2006-06-27 13:25:38.000000', NULL, 1),
(2557976, 350448, 70, '<td valign="top">I like the composition. The hot spot in the back hinders the photo some, though.</td>', 'I like the composition. The hot spot in the back hinders the photo some, though.', '2006-06-27 13:26:00.000000', NULL, 1),
(2557977, 350881, 59138, '<td valign="top">Interesting bokeh.  Dont'' know quite what it is!</td>', 'Interesting bokeh.  Dont'' know quite what it is!', '2006-06-27 13:26:03.000000', NULL, 1),
(2557979, 350417, 59138, '<td valign="top">Nice capture, the bokeh is a bit distracting, that whitish area middle right draws your eye.</td>', 'Nice capture, the bokeh is a bit distracting, that whitish area middle right draws your eye.', '2006-06-27 13:26:43.000000', NULL, 1),
(2557989, 348622, 55738, '<td valign="top">It''s really hard to judge bokeh on such a small image.  Try making it 640 pixels on the long side.</td>', 'It''s really hard to judge bokeh on such a small image.  Try making it 640 pixels on the long side.', '2006-06-27 13:29:48.000000', NULL, 1),
(2557995, 350550, 70, '<td valign="top">Interesting shot. From a composure standpoint, I think moving to the right a bit would have helped. Unfortunately, this looks more like a slightly shallow dof than it does bokeh.</td>', 'Interesting shot. From a composure standpoint, I think moving to the right a bit would have helped. Unfortunately, this looks more like a slightly shallow dof than it does bokeh.', '2006-06-27 13:33:45.000000', NULL, 1),
