(2562542, 349697, 43714, '<td valign="top">Great capture, just beautiful. Congrats</td>', 'Great capture, just beautiful. Congrats', '2006-06-28 15:14:03.000000', NULL, 0),
(2562552, 348584, 43714, '<td valign="top">Beautiful subject and colours, congrats!</td>', 'Beautiful subject and colours, congrats!', '2006-06-28 15:15:33.000000', NULL, 0),
